/**
 * Original Veridoxa UK articles (copyright-safe workflow):
 * - Topics from recent UK public reporting
 * - Fully original wording / structure
 * - Facts cited to official or publisher URLs (links ≠ permission to copy text)
 * - Images: Unsplash stock (illustrative, not event news photos)
 */

const img = (id, w = 900) =>
  `https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=80`

function block(text, style = 'normal') {
  return {
    _type: 'block',
    style,
    children: [{ _type: 'span', text }],
  }
}

function stockImage(photoId, alt) {
  return {
    url: img(photoId),
    alt,
    photographer: 'Unsplash contributor',
    source: 'Unsplash',
    sourceUrl: `https://unsplash.com/photos/${photoId.replace('photo-', '')}`,
    licence: 'Unsplash License',
    attributionRequired: false,
    downloadDate: '2026-11-05',
  }
}

