/** Desk bylines only — never assign real-looking personal names. */
export const deskByCategory = {
  news: 'auth-desk-news',
  politics: 'auth-desk-politics',
  opinion: 'auth-desk-opinion',
  money: 'auth-desk-money',
  culture: 'auth-desk-culture',
  life: 'auth-desk-life',
  sport: 'auth-desk-sport',
}

export function authorForCategory(category) {
  const slug = typeof category === 'string' ? category : category?.slug
  const id = deskByCategory[slug] || 'auth-desk-news'
  return authors.find((a) => a._id === id) || authors[0]
}

const [news, politics, opinion, money, culture, life, sport] = categories

function makeArticle({
  id,
  title,
  slug,
  excerpt,
  photo,
  alt,
  localFile,
  category,
  author,
  publishedAt,
  featured = false,
  isLead = false,
  isLive = false,
  paragraphs,
  sources = [],
}) {
  const mainImage = localFile
    ? {
        localFile,
        // Vite serves files from /public at site root
        url: `/${String(localFile).replace(/^public\//, '')}`,
        alt,
        photographer: 'Veridoxa generated asset',
        source: 'Veridoxa',
        licence: 'Original commissioned illustration',
        attributionRequired: false,
        downloadDate: '2026-11-06',
      }
    : stockImage(photo, alt)

  // Desk bylines only — ignore personal names from drafts/fetched copy
  const resolvedAuthor =
    author && String(author.name || '').startsWith('Magazine ')
      ? author
      : authorForCategory(category)

  return {
    _id: id,
    title,
    slug,
    excerpt,
    mainImage,
    category,
    author: resolvedAuthor,
    publishedAt,
    featured,
    isLead,
    isLive,
    sources,
    body: paragraphs.map((p) =>
      typeof p === 'string' ? block(p) : block(p.text, p.style || 'normal'),
    ),
  }
}

