/** Header / footer section order */
export const navCategories = [
  'News',
  'Politics',
  'Opinion',
  'Money',
  'Culture',
  'Sport',
  'Life',
]

export function sortCategoriesByNav(categories = []) {
  const order = new Map(navCategories.map((title, i) => [title.toLowerCase(), i]))
  return [...categories].sort((a, b) => {
    const aKey = (typeof a === 'string' ? a : a.slug || a.title || '').toLowerCase()
    const bKey = (typeof b === 'string' ? b : b.slug || b.title || '').toLowerCase()
    const ai = order.has(aKey) ? order.get(aKey) : 999
    const bi = order.has(bKey) ? order.get(bKey) : 999
    return ai - bi
  })
}
